import {useEffect,useState} from 'react';
import {ArrowRight,RefreshCw,Send,ShieldCheck,UserRoundPlus} from 'lucide-react';
import {actOnReferral,createReferral,listReferrals} from '../../lib/practiceOperationsApi';

const scopeOptions=['BASIC_PROFILE','CONTACT_DETAILS','PUBLISHED_PLAN','ASSESSMENT_SUMMARY','PROGRESS_SUMMARY','SELECTED_HEALTH_RECORDS','SELECTED_DOCUMENTS','GOALS'];
const tabs=[['outgoing','Outgoing'],['incoming','Incoming'],['drafts','Drafts'],['completed','Completed']];
export function ExternalReferrals({clients=[],clientId=''}){
  const[tab,setTab]=useState(clientId?'outgoing':'outgoing'),[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[open,setOpen]=useState(false);
  const[form,setForm]=useState({client_id:clientId,receiving_profession_code:'PSYCHOLOGIST',destination_name:'',destination_contact:'',reason:'',data_scopes:['BASIC_PROFILE']});
  const direction=tab==='incoming'?'incoming':'outgoing';
  const load=async()=>{setState('loading');setError('');try{const result=await listReferrals(direction,clientId);let rows=result.items||[];if(tab==='drafts')rows=rows.filter(item=>['DRAFT','CONSENT_PENDING','READY_TO_SEND'].includes(item.status));if(tab==='completed')rows=rows.filter(item=>['COMPLETED','DECLINED','CANCELLED'].includes(item.status));setItems(rows);setState('ready')}catch(reason){setError(reason.message||'Referrals could not be loaded.');setState('error')}};
  useEffect(()=>{void load()},[tab,clientId]);
  const save=async event=>{event.preventDefault();setError('');try{await createReferral(form);setOpen(false);await load()}catch(reason){setError(reason.message||'Referral could not be created.')}};
  const transition=async(item,action)=>{setError('');try{await actOnReferral(item.id,action);await load()}catch(reason){setError(reason.message||'Referral action failed.')}};
  return <section className="space-y-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Care</p><h2 className="mt-1 text-3xl font-bold">Referrals</h2><p className="mt-2 text-sm text-slate-600">Consent-first referrals with explicit data scopes. Client ownership is never transferred.</p></div><button onClick={()=>setOpen(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white"><UserRoundPlus className="mr-2 inline" size={17}/>Refer client</button></header>
    <div className="flex gap-2 overflow-x-auto">{tabs.map(([key,label])=><button key={key} onClick={()=>setTab(key)} aria-pressed={tab===key} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-semibold ${tab===key?'bg-blue-700 text-white':'border bg-white'}`}>{label}</button>)}</div>
    {error&&<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-800">{error}</p>}
    {state==='loading'?<div aria-label="Loading referrals" className="h-40 animate-pulse rounded-3xl bg-white"/>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl border px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry referrals</button>:items.length?<div className="grid gap-4 lg:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-3xl border bg-white p-5"><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{item.destination_name||item.receiving_profession_code.replaceAll('_',' ')}</p><p className="mt-1 text-sm text-slate-600">{item.reason}</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-800">{item.status.replaceAll('_',' ')}</span></div><p className="mt-4 text-xs text-slate-500"><ShieldCheck className="mr-1 inline" size={14}/>Consent: {(item.consent_status||'not requested').replaceAll('_',' ')} · scopes: {(item.allowed_data_scopes||[]).join(', ')||'none'}</p><div className="mt-4 flex flex-wrap gap-2">{direction==='outgoing'&&item.status==='DRAFT'&&<button onClick={()=>transition(item,'REQUEST_CONSENT')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Request consent</button>}{direction==='outgoing'&&item.status==='READY_TO_SEND'&&<button onClick={()=>transition(item,'SEND')} className="min-h-11 rounded-xl bg-blue-700 px-3 text-sm font-semibold text-white"><Send className="mr-1 inline" size={15}/>Send</button>}{direction==='incoming'&&item.status==='SENT'&&<><button onClick={()=>transition(item,'ACCEPT')} className="min-h-11 rounded-xl bg-emerald-700 px-3 text-sm font-semibold text-white">Accept</button><button onClick={()=>transition(item,'DECLINE')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Decline</button></>}{['DRAFT','CONSENT_PENDING','READY_TO_SEND','SENT'].includes(item.status)&&direction==='outgoing'&&<button onClick={()=>transition(item,'CANCEL')} className="min-h-11 rounded-xl px-3 text-sm font-semibold text-red-700">Cancel</button>}</div></article>)}</div>:<div className="rounded-3xl border border-dashed bg-white p-8 text-center"><ArrowRight className="mx-auto text-slate-400"/><p className="mt-3 font-semibold">No referrals in this view</p><p className="mt-1 text-sm text-slate-500">This is a confirmed empty state.</p></div>}
    {open&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4" onClick={()=>setOpen(false)}><form onSubmit={save} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="referral-title" className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-6"><h3 id="referral-title" className="text-xl font-bold">Refer client</h3><p className="mt-2 text-sm text-slate-600">Prepare the destination and requested scope, then request client consent before sending.</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Client<select required value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><label className="text-sm font-semibold">Receiving profession<input required value={form.receiving_profession_code} onChange={e=>setForm({...form,receiving_profession_code:e.target.value.toUpperCase().replaceAll(' ','_')})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold">Destination name<input value={form.destination_name} onChange={e=>setForm({...form,destination_name:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold">Destination contact<input value={form.destination_contact} onChange={e=>setForm({...form,destination_contact:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label></div><label className="mt-4 block text-sm font-semibold">Reason<textarea required value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} className="mt-2 min-h-24 w-full rounded-xl border p-3"/></label><fieldset className="mt-4"><legend className="text-sm font-semibold">Requested data scopes</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{scopeOptions.map(scope=><label key={scope} className="flex min-h-11 items-center gap-2 rounded-xl border p-3 text-sm"><input type="checkbox" checked={form.data_scopes.includes(scope)} onChange={e=>setForm({...form,data_scopes:e.target.checked?[...form.data_scopes,scope]:form.data_scopes.filter(value=>value!==scope)})}/>{scope.replaceAll('_',' ')}</label>)}</div></fieldset><p className="mt-4 rounded-xl bg-slate-50 p-3 text-xs text-slate-600">Private notes, raw session notes, internal intelligence, billing, and team notes are always excluded.</p><div className="mt-6 flex gap-3"><button type="button" onClick={()=>setOpen(false)} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button className="min-h-12 flex-1 rounded-xl bg-blue-700 font-semibold text-white">Create draft</button></div></form></div>}
  </section>
}
